export function getTemplate(name) {
  const tmpl = TEMPLATES[name]
  if (!tmpl) {
    const available = getTemplateNames().join(', ')
    throw new Error(
      `Unknown template: "${name}". Available templates: ${available}`,
    )
  }
  return {
    name,
    description: tmpl.description,
    generate: tmpl.generate,
  }
}
